{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Reframe your daily wellness</title>
  <meta name="description" content="Short intensives and habit frameworks to shape sustainable wellness routines. Outcomes, habits, clear practices.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body>
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav" aria-label="Primary">
        <a href="about.html">About</a>
        <a href="programs.html">Immersions</a>
        <a href="services.html">Offerings</a>
        <a href="pricing.html">Rates</a>
        <a href="testimonials.html">Praise</a>
        <a href="book.html" class="cta">Book a Spot</a>
        <a href="contact.html">Contact</a>
      </nav>
      <button class="mobile-toggle" aria-label="Menu">☰</button>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero">
      <div class="pattern" aria-hidden="true"></div>
      <div class="wrap hero-content">
        <div class="hero-copy">
          <h1>Short intensives that rewire daily practice</h1>
          <p class="lede">Practical frameworks, repeatable habits, measurable outcomes — an intensive approach to steadying energy and priorities.</p>
          <p class="meta">Virtual and in-person sessions • Flexible mini-programs</p>
          <div class="actions">
            <a class="primary-cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="muted" href="programs.html">Explore Immersions</a>
          </div>
        </div>
        <aside class="hero-aside">
          <div class="contact-card">
            <strong>Quick connect</strong>
            <a href="tel:{{PHONE}}">{{PHONE}}</a>
            <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>
            <small class="location">Serving {{CITY}}, {{STATE}}</small>
          </div>
        </aside>
      </div>
    </section>

    <!-- PROOF GALLERY -->
    <section id="proof" class="proof-gallery">
      <div class="wrap">
        <h2>Proof — outcomes people return to</h2>
        <p class="sub">Rotating feedback and partner badges that speak to steady results and trust.</p>

        <div class="gallery-grid">
          <div class="testimonials" aria-live="polite">
            <blockquote class="quote">“I gained a compact routine that actually fits my week. Three weeks in and my energy is steadier.”<cite>— S. Ramirez</cite></blockquote>
            <blockquote class="quote">“The frameworks are practical and surprisingly simple. I found a morning reset that lasts.”<cite>— T. Osei</cite></blockquote>
            <blockquote class="quote">“Short, focused sessions that gave me an actionable plan for my days.”<cite>— M. Patel</cite></blockquote>
          </div>

          <div class="credibility">
            <div class="badges">
              <span class="badge" data-tip="Peer-reviewed workshop series">PW</span>
              <span class="badge" data-tip="Featured in local wellness digest">LD</span>
              <span class="badge" data-tip="Corporate pilot programs completed">CP</span>
            </div>
            <div class="gallery-controls">
              <button id="prevQuote" aria-label="Previous testimonial">◀</button>
              <button id="nextQuote" aria-label="Next testimonial">▶</button>
            </div>
            <div class="tooltip" id="badgeTooltip" role="status" aria-hidden="true"></div>
          </div>
        </div>
      </div>
    </section>

    <!-- WHAT TO EXPECT -->
    <section id="expect" class="what-to-expect">
      <div class="wrap">
        <h2>What to expect</h2>
        <div class="expect-grid">
          <div class="card">
            <h3>Outcome-first Intensive</h3>
            <p>Clear milestones for the first 21 days. Every session links to a habit, a metric, and a tiny experiment you can run immediately.</p>
          </div>
          <div class="card">
            <h3>Frameworks to reuse</h3>
            <p>Modular practices you can fold into mornings, midday pauses, and evening wind-downs. No medical advice — only habits and checks.</p>
          </div>
          <div class="card">
            <h3>Measureable habits</h3>
            <p>Simple tracking to keep momentum: a few daily checks that map back to how you feel and what you do next.</p>
          </div>
        </div>

        <div class="pricing-mini">
          <h4>Investment snapshot</h4>
          <div class="toggle" role="tablist" aria-label="Pricing toggle">
            <button class="toggle-btn active" data-mode="monthly" aria-pressed="true">Monthly</button>
            <button class="toggle-btn" data-mode="package" aria-pressed="false">Package</button>
          </div>
          <div class="prices">
            <div class="price-line">Starter: <span class="price" data-month="75" data-package="220">$75</span></div>
            <div class="price-line">Core Intensive: <span class="price" data-month="240" data-package="680">$240</span></div>
            <div class="price-line">Deep Reset: <span class="price" data-month="480" data-package="1290">$480</span></div>
          </div>
          <small class="note">Prices shown as example snapshots. Final rates available during booking.</small>
        </div>
      </div>
    </section>

    <!-- OBJECTIONS -->
    <section id="objections" class="objections">
      <div class="wrap">
        <h2>Common questions</h2>
        <div class="faq-grid">
          <details>
            <summary>Will this work if I'm busy?</summary>
            <p>Frameworks are designed to be modular — take one micro-practice and fold it into an existing routine. The aim is sustainable change, not more tasks.</p>
          </details>
          <details>
            <summary>Is this a coaching or clinical program?</summary>
            <p>Coaching focused on habits, priorities, and outcomes. No medical diagnoses or treatments are offered.</p>
          </details>
          <details>
            <summary>What's the time commitment?</summary>
            <p>Most intensives run 2–6 sessions with brief daily practices. Investment is scaled to the program you choose.</p>
          </details>
        </div>
      </div>
    </section>

    <!-- CTA -->
    <section class="cta-band">
      <div class="wrap">
        <div class="cta-inner">
          <div>
            <h3>Ready to shape a clearer next month?</h3>
            <p>Book a focused strategy session to create one repeatable habit that shifts your week.</p>
          </div>
          <div class="cta-actions">
            <a class="primary-cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="ghost" href="contact.html">Ask a question</a>
          </div>
        </div>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="wrap footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <p>Focused intensives — habits and frameworks to keep day-to-day practice manageable and visible.</p>
      </div>
      <div>
        <nav>
          <a href="about.html">About</a>
          <a href="programs.html">Immersions</a>
          <a href="services.html">Offerings</a>
        </nav>
      </div>
      <div>
        <p><a href="tel:{{PHONE}}">{{PHONE}}</a></p>
        <p><a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
    </div>
    <div class="fineprint">© <span id="year"></span> {{BUSINESS_NAME}} — All rights reserved.</div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
