  "fields":{
    "BUSINESS_NAME":{"label":"Business name","type":"text","default":"Your Practice"},
    "TAGLINE":{"label":"Tagline","type":"text","default":"Intensive approaches to daily practice"},
    "PHONE":{"label":"Phone","type":"text","default":"(555) 555-0100"},
    "EMAIL":{"label":"Email","type":"text","default":"hello@example.com"},
