{"path":"assets/css/styles.css","content":"/* Core styles for clinic_modern / mystic_modern */
:root{
  --bg:#f7f6f9;
  --surface:#ffffff;
  --accent:#6b5bff;
  --muted:#6b7280;
  --text:#0f172a;
  --radius:10px;
}
*{box-sizing:border-box}
html,body{height:100%;margin:0;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;color:var(--text);background:var(--bg);}
.wrap{max-width:1100px;margin:0 auto;padding:28px}
.site-header{background:linear-gradient(180deg,rgba(255,255,255,0.9),transparent);backdrop-filter:saturate(120%);position:sticky;top:0;z-index:30;border-bottom:1px solid rgba(15,23,42,0.04)}
.site-header .wrap{display:flex;align-items:center;gap:18px}
.brand{font-weight:700;color:var(--text);text-decoration:none;font-size:18px}
.main-nav{margin-left:auto;display:flex;gap:12px;align-items:center}
.main-nav a{color:var(--muted);text-decoration:none;padding:8px 10px;border-radius:8px}
.main-nav a.cta{background:var(--accent);color:white}
.mobile-toggle{display:none;background:none;border:0;font-size:20px}
.hero{padding:44px 0;position:relative;overflow:hidden}
.hero .pattern{position:absolute;right:-20%;top:-20%;width:60%;height:140%;background-image:url('/assets/img/pattern.svg');background-repeat:no-repeat;opacity:0.14;transform:rotate(8deg)}
.hero .hero-content{display:flex;gap:28px;align-items:flex-start}
.hero-copy{flex:1}
.hero-copy h1{font-size:34px;margin:0 0 10px}
.lede{color:var(--muted);margin:0 0 8px}
.meta{font-size:13px;color:var(--muted);margin-bottom:18px}
.actions{display:flex;gap:12px}
.primary-cta{background:var(--accent);color:white;padding:12px 16px;border-radius:9px;text-decoration:none}
.muted{color:var(--accent);text-decoration:none;padding:12px 16px;border-radius:9px;border:1px solid rgba(107,91,255,0.12)}
.hero-aside{width:240px}
.contact-card{background:var(--surface);padding:14px;border-radius:12px;box-shadow:0 6px 18px rgba(15,23,42,0.06)}
.contact-card a{display:block;color:var(--accent);text-decoration:none}
.location{font-size:12px;color:var(--muted)}
.proof-gallery{padding:36px 0}
.proof-gallery h2{margin:0 0 6px}
.gallery-grid{display:grid;grid-template-columns:1fr 220px;gap:18px;align-items:start}
.testimonials{background:var(--surface);padding:20px;border-radius:12px;min-height:140px;display:flex;align-items:center;justify-content:center;position:relative}
.quote{display:none;font-size:16px;line-height:1.4;margin:0}
.quote cite{display:block;margin-top:10px;font-size:13px;color:var(--muted)}
.testimonials .quote.show{display:block}
.credibility{display:flex;flex-direction:column;gap:12px;align-items:center}
.badges{display:flex;gap:8px}
.badge{display:inline-flex;width:44px;height:44px;border-radius:8px;background:linear-gradient(180deg,#fff,#f3f2ff);align-items:center;justify-content:center;font-weight:700;color:var(--accent);cursor:default;position:relative}
.gallery-controls button{background:transparent;border:1px solid rgba(15,23,42,0.06);padding:8px;border-radius:8px;cursor:pointer}
.tooltip{position:absolute;background:var(--surface);padding:8px 10px;border-radius:8px;box-shadow:0 6px 24px rgba(15,23,42,0.08);display:none;font-size:13px}
.what-to-expect{padding:36px 0}
.expect-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-bottom:18px}
.card{background:var(--surface);padding:18px;border-radius:12px}
.pricing-mini{background:linear-gradient(180deg,#fff,#fbfbff);padding:16px;border-radius:12px;margin-top:8px}
.toggle{display:inline-flex;border-radius:999px;background:rgba(15,23,42,0.04);padding:6px}
.toggle-btn{border:0;background:transparent;padding:8px 14px;border-radius:999px;cursor:pointer}
.toggle-btn.active{background:var(--accent);color:white}
.prices{margin-top:12px}
.price-line{font-weight:600;color:var(--text);margin-bottom:6px}
.price{color:var(--accent)}
.objections{padding:36px 0}
.faq-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.faq-grid details{background:var(--surface);padding:14px;border-radius:10px}
.cta-band{background:linear-gradient(180deg,#fff,#f7f6ff);padding:22px 0;margin-top:18px}
.cta-inner{display:flex;justify-content:space-between;align-items:center}
.ghost{background:transparent;color:var(--muted);padding:10px 14px;border-radius:9px;text-decoration:none}
.site-footer{padding:24px 0;margin-top:18px;border-top:1px solid rgba(15,23,42,0.04)}
.footer-grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:18px}
.fineprint{text-align:center;color:var(--muted);font-size:13px;margin-top:10px}
@media (max-width:900px){
  .wrap{padding:20px}
  .hero .hero-content{flex-direction:column}
  .gallery-grid{grid-template-columns:1fr}
  .expect-grid{grid-template-columns:1fr}
  .faq-grid{grid-template-columns:1fr}
  .main-nav{display:none}
  .mobile-toggle{display:block;margin-left:auto}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Populate year
  document.addEventListener('DOMContentLoaded',function(){
    var y=document.getElementById('year'); if(y) y.textContent=new Date().getFullYear();

    // Testimonials rotation
    var quotes=document.querySelectorAll('.testimonials .quote');
    var idx=0; function show(i){quotes.forEach(function(q){q.classList.remove('show')});quotes[i].classList.add('show')}
    if(quotes.length){ show(0); var rot=setInterval(function(){ idx=(idx+1)%quotes.length; show(idx); },5000);
      document.getElementById('prevQuote').addEventListener('click',function(){ clearInterval(rot); idx=(idx-1+quotes.length)%quotes.length; show(idx); });
      document.getElementById('nextQuote').addEventListener('click',function(){ clearInterval(rot); idx=(idx+1)%quotes.length; show(idx); });
    }

    // Badge tooltip
    var badges=document.querySelectorAll('.badge');
    var tt=document.getElementById('badgeTooltip');
    badges.forEach(function(b){
      b.addEventListener('mouseover',function(e){ var tip=b.getAttribute('data-tip'); if(!tip) return; tt.textContent=tip; tt.style.display='block'; tt.setAttribute('aria-hidden','false'); var r=b.getBoundingClientRect(); var parent=document.querySelector('.credibility'); var pr=parent.getBoundingClientRect(); tt.style.left=(r.left-pr.left)+'px'; tt.style.top=(r.bottom-pr.top+8)+'px'; });
      b.addEventListener('mouseout',function(){ tt.style.display='none'; tt.setAttribute('aria-hidden','true'); });
    });

    // Pricing comparator
    var toggleBtns=document.querySelectorAll('.toggle-btn');
    var priceEls=document.querySelectorAll('.price');
    function animatePrice(el,from,to){
      var start=+from; var end=+to; var dur=420; var startTime=Date.now(); var raf=function(){ var now=Date.now(); var t=Math.min(1,(now-startTime)/dur); var val=Math.round(start+(end-start)*t); el.textContent='$'+val; if(t<1) requestAnimationFrame(raf); };
      requestAnimationFrame(raf);
    }
    toggleBtns.forEach(function(btn){ btn.addEventListener('click', function(){ toggleBtns.forEach(function(b){b.classList.remove('active');b.setAttribute('aria-pressed','false')}); btn.classList.add('active'); btn.setAttribute('aria-pressed','true'); var mode=btn.getAttribute('data-mode'); priceEls.forEach(function(pe){ var current=pe.textContent.replace(/[^0-9]/g,'')||'0'; var target=pe.getAttribute('data-'+mode); animatePrice(pe,current,target); }); }); });

    // Mobile menu
    var mt=document.querySelector('.mobile-toggle'); if(mt){ mt.addEventListener('click',function(){ var nav=document.querySelector('.main-nav'); if(nav.style.display==='flex'){nav.style.display='none';}else{nav.style.display='flex';nav.style.flexDirection='column';}}); }
  });
})();"} 
